import { RootFocusBoundary, useFocusable } from "@roku-sdk/navigation";
import { type AnchorNodeImplementation, defineAnchorNode, FieldType } from "@roku-sdk/rsg-ts";

// The app's one anchor node: the scene holds it, and the remote's keys reach its focus boundary through keyEvent.
// Keys it doesn't handle go back to the scene, so Back on the first screen leaves the app.
const AppDescription = {
    componentName: "App",
    extends: "FocusBoundaryBase" as const,
    inputFields: {
        keyEvent: FieldType.Object(),
        focusActive: FieldType.Boolean(true)
    },
    outputFields: {
        handledKeys: FieldType.Object()
    }
};

const titleId: object = {};

const Title = () => {
    const { ref, isFocused } = useFocusable({ focusId: titleId });
    return (
        <group ref={ref}>
            <label
                text="{{NAME}}"
                color={isFocused() ? "0xFFFFFFFF" : "0xB0B4BAFF"}
                font="font:LargeBoldSystemFont"
                horizAlign="center"
                vertAlign="center"
                width={1920}
                height={1080}
            />
        </group>
    );
};

const App: AnchorNodeImplementation<typeof AppDescription> = (inputs, outputs) => (
    <RootFocusBoundary
        keyEvent={inputs.keyEvent as Parameters<typeof RootFocusBoundary>[0]["keyEvent"]}
        focusActive={inputs.focusActive as boolean}
        setHandledKeys={outputs.handledKeys}
        initialFocus={titleId}
    >
        <rectangle width={1920} height={1080} color="0x101418FF" />
        <Title />
    </RootFocusBoundary>
);

export default defineAnchorNode(AppDescription, App);

